import numpy as np
from numba import njit

@njit(cache=True)
def auction(c, cand):
 n,k=cand.shape; pr=np.zeros(n); own=np.full(n,-1,np.int64); ass=np.empty(n,np.int64); st=np.empty(n,np.int64)
 eps=.01
 while eps>1e-13:
  own[:]=-1;ass[:]=-1
  for i in range(n):st[i]=i
  top=n
  while top:
   top-=1;i=st[top];x=1e300;y=1e300;bj=0
   for q in range(k):
    j=cand[i,q];z=c[i,j]+pr[j]
    if z<x:y=x;x=z;bj=j
    elif z<y:y=z
   pr[bj]+=y-x+eps;old=own[bj];own[bj]=i;ass[i]=bj
   if old>=0:ass[old]=-1;st[top]=old;top+=1
  eps*=.01
 return ass,pr

@njit(cache=True)
def certified(c,ass,pr):
 n=c.shape[0]
 for i in range(n):
  x=c[i,ass[i]]+pr[ass[i]]
  mn=1e300
  for j in range(n):
   z=c[i,j]+pr[j]
   if z<mn:mn=z
  if x>mn+1e-9:return False
 return True

class Solver:
 def solve(self,p,**kw):
  M=np.asarray(p['cost_matrix'],dtype=np.float64);n=M.shape[0];k=min(128,n)
  cand=np.argpartition(M,k-1,axis=1)[:,:k].astype(np.int64)
  a,pr=auction(M,cand)
  if not certified(M,a,pr):
   cand=np.tile(np.arange(n,dtype=np.int64),(n,1));a,pr=auction(M,cand)
  G=np.zeros(M.shape);G[np.arange(n),a]=np.asarray(p['source_weights'])
  return {'transport_plan':G}

