  M=np.asarray(problem['cost_matrix'],dtype=np.float64); n=M.shape[0]; cols=_hungarian(M)
  G=np.zeros(M.shape);G[np.arange(n),cols]=np.asarray(problem['source_weights'])
  return {'transport_plan':G}
